section.para:
An example in CG format, converted with cg-conv -c -D --deleted -J:

  <STREAMCMD:SETVAR:genre=news,draft>
  "<The>" <cap>
    "the" DET @>N #1->2
  "<cats>"
    "cat" N PL @SUBJ> #2->3
  ;  "cat" V PRES #2->3
  "<haven't>"
    "not" ADV #3->0
      "have" V PRES
  "<.>"
    "." CLB #4->3
  A line of text
  <STREAMCMD:FLUSH>


  {"cmd":"<STREAMCMD:SETVAR:genre=news>"}
  {"cmd":"<STREAMCMD:SETVAR:draft>"}
  {"w":"The","sts":["<cap>"],"ds":1,"dp":2,"rs":[{"l":"the","ts":["DET","@>N"]}]}
  {"w":"cats","ds":2,"dp":3,"rs":[{"l":"cat","ts":["N","PL","@SUBJ>"]}],"drs":[{"l":"cat","ts":["V","PRES"]}]}
  {"w":"haven't","ds":3,"dp":0,"rs":[{"l":"not","ts":["ADV"],"s":{"l":"have","ts":["V","PRES"]}}]}
  {"w":".","z":"A line of text","ds":4,"dp":3,"rs":[{"l":".","ts":["CLB"]}]}
  {"cmd":"<STREAMCMD:FLUSH>"}
